const round = (n) => Math.round(n * 10) / 10;
const totals = (items) => items.reduce((sum, [id, amount]) => {
  const factor = id === 'eggs' ? amount * 0.5 : amount / 100;
  return sum.map((n, i) => n + products[id][i + 2] * factor);
}, [0, 0, 0, 0]);
const storage = 'Лучше подать свежим. Остатки быстро охладить, убрать в холодильник в течение 1–2 часов и использовать в пределах 48 часов либо заморозить порционно. Разогреть один раз до горячего центра. Свежий огурец и зелень хранить отдельно; после замораживания они теряют текстуру.';
