// Adjust only grains, potato, oil and nuts, keeping protein, eggs and fruit portions intact.
// These are new recipe estimates, not the original Word totals.
for (const menu of ['document', 'variety']) for (let day = 1; day <= 7; day++) {
  const meals = raw.filter((r) => r.menu === menu && r.day === day);
  const adjustable = new Set(['oats','rice','quinoa','buckwheat','potato','olive-oil','butter','walnut','pecan','pasta','bread','rice-cakes']);
  const all = meals.flatMap((r) => r.items);
  const fixed = totals(all.filter(([id]) => !adjustable.has(id)))[0];
  const variable = totals(all.filter(([id]) => adjustable.has(id)))[0];
  const factor = (1325 - fixed) / variable;
  if (factor < 0.5 || factor > 1.6) throw new Error(`Unreasonable calorie adjustment: ${menu}/${day}`);
  for (const r of meals) for (const item of r.items) if (adjustable.has(item[0])) item[1] = round(item[1] * factor);
}

function build(r, index) {
  const options = r.options;
  const items = r.items;
  // Explicit total water covers all sequential TM6 steps; unused cooking water is discarded.
  if (!items.some(([id]) => id === 'water')) {
    const water = r.kind === 'oats' ? (items.find(([id]) => id === 'oats')?.[1] ?? 0) * 5 : ['main','eggs','omelet'].includes(r.kind) ? 1000 : 0;
    if (water) items.push(['water',water]);
  }
  if (!['snack','toast','sorbet','pancakes','porridge','oats'].includes(r.kind)) items.push(['salt',0.5]);
  const details = instructions(r.kind, items, options);
  const nutrition = totals(items);
  const id = `fodmap-${r.menu}-${r.day}-${index + 1}`;
  const category = {Завтрак:'Завтраки',Обед:'Обеды',Ужин:'Ужины',Перекус:'Перекусы',Десерт:'Десерты'}[r.label];
  const has = (key) => items.some(([id]) => id === key);
  const notes = [baseTolerance];
  if (has('banana')) notes.push('Банан только плотный, не переспелый; начальная порция здесь 50 г на человека. При реакции не использовать.');
  if (has('avocado') || has('coconut') || has('zucchini') || has('strawberry')) notes.push('Порцию авокадо, кокосового молока, кабачка и ягод, если они указаны, особенно важно сверить в Monash: цифры здесь — кулинарные количества, не лабораторные пороги.');
  if (has('cranberry')) notes.push('Клюква кислая: при изжоге заменить переносимой ягодой с пересчётом КБЖУ. Сушёная подслащённая клюква не равнозначна свежей.');
  if (has('parmesan') || has('tuna')) notes.push('Пармезан и консервированный тунец оставлены из исходника. При отдельном низкогистаминовом ограничении нужна замена и пересчёт; этот набор не низкогистаминовый.');
  const estimatedWeight = items.filter(([id]) => id !== 'water').reduce((s,[id,n]) => s + (id === 'eggs' ? n * 50 : n),0) + items.filter(([id]) => ['rice','quinoa','buckwheat','pasta'].includes(id)).reduce((s,[,n])=>s+n*2,0) + (r.kind === 'soup' ? 250 : r.kind === 'oats' ? (items.find(([id])=>id==='oats')?.[1]??0)*5 : r.kind === 'porridge' ? (items.find(([id])=>id==='water')?.[1]??0) : 0);
  return { id, slug:id, title:r.title, description:`${r.label}. ${r.menu === 'document' ? 'Адаптация меню из Word' : 'Адаптация разнообразного меню'}: на двоих, с приблизительным расчётом на одного.`, category, day:r.day, servings:2, portions:'2 равные порции: Маша и Максим', activeMinutes:r.kind === 'snack' ? 5 : r.kind === 'sorbet' ? 10 : r.kind === 'soup' ? 20 : 15, totalMinutes:r.kind === 'snack' ? 5 : r.kind === 'toast' ? 15 : r.kind === 'sorbet' ? 10 : r.kind === 'oats' ? 25 : r.kind === 'porridge' ? 50 : r.kind === 'soup' ? 50 : options.casserole ? 85 : r.kind === 'pancakes' ? 25 : r.kind === 'omelet' ? has('potato') ? 45 : has('salmon') ? 40 : 20 : 70, ...details, ingredients:items.map(ingredient), storage:has('rice') ? riceStorage : r.kind === 'sorbet' ? 'Подать сразу. Повторно не замораживать оттаявшие ягоды; готовый сорбет теряет мягкость при хранении.' : r.kind === 'snack' ? 'Собирать перед подачей. Нарезанные фрукты и открытый йогурт держать в холодильнике по маркировке, желательно использовать в день приготовления.' : storage, substitutions:'Курицу можно заменить индейкой, треску — другим филе белой рыбы. КБЖУ после замены пересчитать. Продукты с глютеном заменить аналогами с маркировкой bez glutenu, если это необходимо; отсутствие глютена само по себе не означает Low FODMAP.', tolerance:notes.join(' '), status:'testing', source:r.menu==='document' ? 'Menu_KBZHU.docx — 7 дней; количества и способы адаптированы' : 'Присланный текст — разнообразное меню на 7 дней; томаты заменены, лимон к основным блюдам не добавлен', collection:'fodmap', menu:r.menu, meal:r.label, nutrition:{kcal:Math.round(nutrition[0]),protein:round(nutrition[1]),fat:round(nutrition[2]),carbs:round(nutrition[3])}, nutritionNote:'Приблизительно по справочной таблице ингредиентов; показатели бренда могут отличаться. На человека — половина всех ингредиентов. Напитки, VIANESSE и дополнительные блюда не включены.', portionWeight:`Ориентир порции: около ${Math.round(estimatedWeight/10)*10} г до поправки на испарение; взвесьте выход и разделите поровну. Крупы в ингредиентах указаны сухими.`, batchNote:'Количество ингредиентов — на двоих. Если готовите один день полностью, учитывайте все карточки этого дня.' };
}

export const fodmapRecipes = raw.map(build);

function extra(id, title, category, items, steps, equipment, totalMinutes, note, tolerance, portions = '2 порции: по одной на человека') {
  const n = totals(items);
  fodmapRecipes.push({id:`fodmap-extra-${id}`,slug:`fodmap-extra-${id}`,title,description:note,category,day:0,servings:2,portions,activeMinutes:Math.min(15,totalMinutes),totalMinutes,equipment,methods:equipment.includes('Духовка') ? ['Thermomix','Духовка'] : ['Thermomix'],ingredients:items.map(ingredient),steps,storage:category==='Хлеб' ? 'Полностью остудить на решётке, нарезать. Порции, которые не съедите в день выпечки, заморозить. Разогревать ломтиками в духовке. Творожный мякиш после замораживания может стать суше.' : id==='pudding' ? riceStorage : storage,substitutions:'Замена продукта требует пересчёта КБЖУ. Для молочных ингредиентов использовать маркировку bez laktozy.',tolerance:`${baseTolerance} ${tolerance}`,status:'testing',source:'Отдельный рецепт из присланных текстов; адаптация TM6',collection:'fodmap',menu:'extras',meal:'Дополнительно',nutrition:{kcal:Math.round(n[0]),protein:round(n[1]),fat:round(n[2]),carbs:round(n[3])},nutritionNote:'Приблизительно на половину всей закладки. Дополнительное блюдо не включено в итог дней; при замене вычтите заменяемое блюдо и добавьте это.',portionWeight:category==='Хлеб' ? 'Расчёт на половину буханки для хранения. Для еды начните с 35–40 г; взвесьте готовый хлеб, КБЖУ ломтика = КБЖУ половины × масса ломтика / масса половины.' : id==='pudding' ? 'Примерно 220–250 г на человека; зависит от испарения.' : 'Соус: половина выхода на человека; взвесьте готовый соус и разделите поровну.',batchNote:note});
}
